  (
    'Who wrote the novel Pride and Prejudice?',
    'Literature',
    'easy',
    '["Charlotte Brontë","Jane Austen","Mary Shelley","Virginia Woolf"]'::jsonb,
    1,
    'Jane Austen published Pride and Prejudice in 1813.',
    true
