  (
    'Who painted The Starry Night?',
    'Art',
    'easy',
    '["Claude Monet","Pablo Picasso","Vincent van Gogh","Paul Cézanne"]'::jsonb,
    2,
    'Van Gogh painted The Starry Night in 1889 while staying at an asylum in Saint-Rémy-de-Provence.',
    true
  ),
  (
    'What does the Japanese word arigato mean?',
    'Language',
    'easy',
    '["Hello","Goodbye","Thank you","Please"]'::jsonb,
    2,
    'Arigato is a common way to say thank you. The fuller form is arigato gozaimasu.',
    true
  ),
  (
    'In tennis, what is a score of zero called?',
    'Sport',
    'medium',
    '["Nil","Duck","Love","Blank"]'::jsonb,
    2,
    'Tennis uses love for zero. A player with no points has love.',
    true
  ),
  (
    'What is the largest animal alive today?',
    'Nature',
    'easy',
    '["African elephant","Blue whale","Giraffe","Great white shark"]'::jsonb,
    1,
    'The blue whale is the largest animal known to have ever lived.',
    true
  ),
  (
    'As of 2025, which planet has the most confirmed moons?',
    'Space',
    'hard',
